import java.math.BigInteger

const val MOD = 1000000007

fun main() {
    val m = readln().toLong()
    val digits = m.toString().map { it - '0' }.toList()
    val n = digits.size

    // Precompute factorials and inverse factorials up to 7
    val fact = LongArray(8) { 1 }
    for (i in 1..7) fact[i] = fact[i - 1] * i % MOD
    val invFact = LongArray(8) { 1 }
    invFact[7] = modPow(fact[7], MOD - 2)
    for (i in 6 downTo 0) invFact[i] = invFact[i + 1] * (i + 1) % MOD

    // nCr
    fun nCr(n: Int, r: Int): Long {
        if (r < 0 || r > n) return 0
        return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD
    }

    // DP to count numbers in [1, m] with exactly k lucky digits
    // dp[pos][tight][count]
    val maxL = n
    val dp = Array(n + 1) { Array(2) { LongArray(maxL + 1) } }
    dp[0][1][0] = 1

    for (pos in 0 until n) {
        for (tight in 0..1) {
            for (cnt in 0..maxL) {
                val cur = dp[pos][tight][cnt]
                if (cur == 0L) continue
                val limit = if (tight == 1) digits[pos] else 9
                for (d in 0..limit) {
                    val ntight = if (tight == 1 && d == limit) 1 else 0
                    val ncnt = cnt + if (d == 4 || d == 7) 1 else 0
                    if (ncnt <= maxL) {
                        dp[pos + 1][ntight][ncnt] = (dp[pos + 1][ntight][ncnt] + cur) % MOD
                    }
                }
            }
        }
    }

    val count = LongArray(maxL + 1)
    for (tight in 0..1) {
        for (cnt in 0..maxL) {
            count[cnt] = (count[cnt] + dp[n][tight][cnt]) % MOD
        }
    }
    // Subtract 0 (number 0) if it was counted
    count[0] = (count[0] - 1 + MOD) % MOD

    // Now we have count[k] = number of integers in [1, m] with exactly k lucky digits
    // We need to choose 7 distinct numbers from [1, m]
    // One is for LEPP, six for others.
    // Condition: luckyDigits(LEPP) > sum(luckyDigits(others))

    // Total numbers available = m
    // We iterate over possible lucky digit count L for LEPP (1..maxL)
    // For each L, we choose 1 number from count[L] for LEPP
    // Then we need to choose 6 numbers from the remaining numbers such that sum of their lucky digits < L
    // This is a combinatorial selection without replacement from groups.

    // Since m can be large (1e9), but maxL <= 10 (digits of 1e9 is 10), and we only pick 7 numbers,
    // we can use DP over the groups of lucky digit counts.
    // There are at most 11 groups (0 to 10).
    // We need to pick 6 items from groups with weight = lucky digit count, total weight < L.

    var ans = 0L
    for (L in 1..maxL) {
        if (count[L] == 0L) continue
        // Choose LEPP number
        val waysLEPP = count[L]

        // Remaining counts
        val rem = count.copyOf()
        rem[L] = (rem[L] - 1 + MOD) % MOD

        // DP to pick 6 numbers with sum of lucky digits < L
        // dp2[i][j] = ways to pick i numbers with total lucky digits = j
        val dp2 = Array(7) { LongArray(L) } // j from 0 to L-1
        dp2[0][0] = 1

        for (k in 0..maxL) {
            val c = rem[k]
            if (c == 0L) continue
            // We can pick t numbers from this group, t = 0..min(6, c)
            // But since we only need up to 6 total, and c can be huge, we use combination formula
            // However, we are picking without replacement from a pool of size c.
            // The number of ways to pick t items from c is C(c, t).
            // We need to update dp2.
            // Iterate t from 1 to min(6, c) but c can be large, but we only care up to 6.
            val maxT = minOf(6, c.toInt()) // c is modulo MOD, but actual c can be > MOD? count is modulo MOD, but actual count might be > MOD.
            // However, m <= 1e9, so count[k] <= 1e9 < MOD. So c is actual count.
            for (t in 1..maxT) {
                val comb = nCr(c.toInt(), t)
                val weight = k * t
                // Update dp2 in reverse order of i
                for (i in 6 - t downTo 0) {
                    for (j in 0..L - 1 - weight) {
                        if (dp2[i][j] != 0L) {
                            dp2[i + t][j + weight] = (dp2[i + t][j + weight] + dp2[i][j] * comb) % MOD
                        }
                    }
                }
            }
        }

        var waysOthers = 0L
        for (j in 0..L - 1) {
            waysOthers = (waysOthers + dp2[6][j]) % MOD
        }

        ans = (ans + waysLEPP * waysOthers) % MOD
    }

    println(ans)
}

fun modPow(a: Long, e: Long): Long {
    var res = 1L
    var base = a % MOD
    var exp = e
    while (exp > 0) {
        if (exp and 1L == 1L) res = res * base % MOD
        base = base * base % MOD
        exp = exp shr 1
    }
    return res
}
